"use client";

import { useCallback, useEffect, useState } from "react";

export type PlaceSuggestion = {
  id: string;
  title: string;
  subtitle: string;
  description: string;
  types: string[];
  latitude: number | null;
  longitude: number | null;
};

export type AutocompleteStatus = "idle" | "loading" | "success" | "error";

const API_BASE = (
  process.env.NEXT_PUBLIC_API_URL ?? "http://localhost:3000"
).replace(/\/+$/, "");
const ENDPOINT = `${API_BASE}/api/v1/places/autocomplete`;

// Small in-memory LRU cache shared across component instances.
const CACHE_LIMIT = 50;
const cache = new Map<string, PlaceSuggestion[]>();

function cacheGet(key: string): PlaceSuggestion[] | undefined {
  const hit = cache.get(key);
  if (hit) {
    cache.delete(key);
    cache.set(key, hit); // mark as most recently used
  }
  return hit;
}

function cacheSet(key: string, value: PlaceSuggestion[]) {
  cache.set(key, value);
  if (cache.size > CACHE_LIMIT) {
    const oldest = cache.keys().next().value;
    if (oldest !== undefined) cache.delete(oldest);
  }
}

/** Converts the API response `{ success, data: [...] }` into typed suggestions. */
function parseSuggestions(json: unknown): PlaceSuggestion[] {
  const raw = (json as { data?: unknown } | null)?.data;
  if (!Array.isArray(raw)) return [];

  const seen = new Set<string>();
  const out: PlaceSuggestion[] = [];

  for (const item of raw) {
    if (!item || typeof item !== "object") continue;
    const r = item as Record<string, unknown>;

    const description = typeof r.description === "string" ? r.description : "";
    const mainText = typeof r.mainText === "string" ? r.mainText : "";
    const title = mainText || description;
    if (!title) continue;

    const id =
      typeof r.placeId === "string" && r.placeId ? r.placeId : description || title;
    if (seen.has(id)) continue;
    seen.add(id);

    out.push({
      id,
      title,
      subtitle: typeof r.secondaryText === "string" ? r.secondaryText : "",
      description: description || title,
      types: Array.isArray(r.types)
        ? r.types.filter((t): t is string => typeof t === "string")
        : [],
      latitude: typeof r.latitude === "number" ? r.latitude : null,
      longitude: typeof r.longitude === "number" ? r.longitude : null,
    });
  }

  return out;
}

type Options = {
  minChars?: number;
  debounceMs?: number;
};

export function usePlacesAutocomplete({
  minChars = 2,
  debounceMs = 250,
}: Options = {}) {
  // `query` is what the input shows. `searchTerm` is what we actually fetch for.
  // Keeping them separate lets us fill the input on selection without
  // triggering a new request.
  const [query, setQuery] = useState("");
  const [searchTerm, setSearchTerm] = useState("");
  const [suggestions, setSuggestions] = useState<PlaceSuggestion[]>([]);
  const [status, setStatus] = useState<AutocompleteStatus>("idle");

  /** Call when the user types. */
  const onType = useCallback((value: string) => {
    setQuery(value);
    setSearchTerm(value);
  }, []);

  /** Call when the user picks a suggestion: fills the input, no fetch. */
  const choose = useCallback((value: string) => {
    setQuery(value);
    setSearchTerm("");
  }, []);

  /** Call on focus: re-runs the search for the current text (cache makes it instant). */
  const resume = useCallback(() => {
    setSearchTerm((prev) => (prev === query ? prev : query));
  }, [query]);

  const clear = useCallback(() => {
    setQuery("");
    setSearchTerm("");
  }, []);

  useEffect(() => {
    const term = searchTerm.trim();

    if (term.length < minChars) {
      setSuggestions([]);
      setStatus("idle");
      return;
    }

    const key = term.toLowerCase();
    const cached = cacheGet(key);
    if (cached) {
      setSuggestions(cached);
      setStatus("success");
      return;
    }

    setStatus("loading");
    const controller = new AbortController();

    const timer = setTimeout(async () => {
      try {
        const res = await fetch(`${ENDPOINT}?input=${encodeURIComponent(term)}`, {
          signal: controller.signal,
          headers: { Accept: "application/json" },
        });
        if (!res.ok) throw new Error(`HTTP ${res.status}`);

        const list = parseSuggestions(await res.json());
        cacheSet(key, list);
        setSuggestions(list);
        setStatus("success");
      } catch (err) {
        if (controller.signal.aborted) return; // superseded by a newer request
        console.error("Places autocomplete failed:", err);
        setSuggestions([]);
        setStatus("error");
      }
    }, debounceMs);

    return () => {
      clearTimeout(timer);
      controller.abort();
    };
  }, [searchTerm, minChars, debounceMs]);

  return {
    query,
    onType,
    choose,
    resume,
    clear,
    suggestions,
    status,
    hasTerm: searchTerm.trim().length >= minChars,
  };
}