"use client";
import { useEffect, useState } from "react";
import { getCookie, hasCookie } from "cookies-next";
import getUserDetail from "@/services/auth/userDetail";
import downloadRequest from "@/services/downloadBrochureService";
import styles from "./route-modal.module.scss";

// Modern, in-pane version of tour-detail-page/download-brochure-modal.tsx —
// same service + payload, restyled to live inside the route modal.
export default function BrochureForm({
  tourSlug,
  onBack,
}: {
  tourSlug: string;
  onBack: () => void;
}) {
  const [isActiveUser, setIsActiveUser] = useState(false);
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [sending, setSending] = useState(false);
  const [sent, setSent] = useState(false);
  const [error, setError] = useState("");

  useEffect(() => {
    if (hasCookie("auth-token")) {
      getUserDetail({ token: getCookie("auth-token") })
        .then((res: any) => {
          setIsActiveUser(true);
          setName(res.name ?? "");
          setEmail(res.email ?? "");
        })
        .catch(() => {});
    }
  }, []);

  const submit = () => {
    if (name.trim() === "" || email.trim() === "") {
      setError("Please fill in the required fields.");
      return;
    }
    setError("");
    setSending(true);

    downloadRequest({
      data: {
        slug: tourSlug,
        first_name: name,
        email,
        // Varsa apiv3 token'ı: talep login'li kullanıcıya bağlanır.
        token: getCookie("auth-token-v3")?.toString(),
      },
    })
      .then(() => {
        setSending(false);
        setSent(true);
      })
      .catch(() => {
        setSending(false);
        setError("There is a problem. Please try again later.");
      });
  };

  return (
    <div className={styles.formPane}>
      <div className={styles.formHead}>
        <button
          type="button"
          className={styles.back}
          onClick={onBack}
          aria-label="Back to route"
        >
          <svg
            width={18}
            height={18}
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            strokeWidth={2}
            strokeLinecap="round"
            strokeLinejoin="round"
          >
            <path d="M15 18l-6-6 6-6" />
          </svg>
        </button>
        <h3 className={styles.formTitle}>Download Brochure</h3>
      </div>

      <div className={styles.formBody}>
        {sent ? (
          <div className={styles.formSuccess}>
            <div className={styles.successIcon}>
              <svg
                width={26}
                height={26}
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                strokeWidth={2}
                strokeLinecap="round"
                strokeLinejoin="round"
              >
                <path d="M20 6L9 17l-5-5" />
              </svg>
            </div>
            <p className="tw-mb-0">
              We&apos;ve sent the brochure to <strong>{email}</strong>. Please
              check your inbox!
            </p>
          </div>
        ) : (
          <>
            <p className={styles.formIntro}>
              {isActiveUser
                ? "We'll send the tour brochure as a PDF to your email address below."
                : "Enter your details and we'll email you the brochure with all the important information."}
            </p>

            {error && <div className={styles.formError}>{error}</div>}

            <div className={styles.fieldRow}>
              <div className={styles.field}>
                <label className={styles.label}>
                  First Name <span className={styles.req}>*</span>
                </label>
                <input
                  type="text"
                  className={styles.input}
                  placeholder="Your name"
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                  readOnly={isActiveUser}
                />
              </div>
              <div className={styles.field}>
                <label className={styles.label}>
                  Email <span className={styles.req}>*</span>
                </label>
                <input
                  type="email"
                  className={styles.input}
                  placeholder="you@example.com"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  readOnly={isActiveUser}
                />
              </div>
            </div>

            {/* Button flows at the end of the scrollable form body (not a
                pinned footer): avoids the iOS Safari bug where a fixed-bottom
                control hides behind the toolbar/keyboard after input blur. */}
            <div className={styles.actions}>
              <button
                type="button"
                className={`tw-inline-flex tw-items-center tw-justify-center tw-bg-[#854ec9] hover:tw-bg-[#6a3da4] tw-text-white tw-border-0 tw-cursor-pointer tw-no-underline tw-transition-colors disabled:tw-opacity-60 disabled:tw-cursor-not-allowed ${styles.viewTour}`}
                onClick={submit}
                disabled={sending}
              >
                {sending ? (
                  <>
                    <span
                      className="tw-inline-block tw-w-4 tw-h-4 tw-mr-2 tw-rounded-full tw-border-2 tw-border-solid tw-border-current tw-border-r-transparent tw-animate-spin tw-align-[-0.125em]"
                      role="status"
                      aria-hidden="true"
                    />
                    Sending…
                  </>
                ) : (
                  "Download"
                )}
              </button>
            </div>
          </>
        )}
      </div>
    </div>
  );
}
