"use client";
import React, {
  useState,
  useEffect,
  useRef,
  useMemo,
  useId,
  useCallback,
} from "react";
import { useRouter } from "next/navigation";
import DateField from "./date-field";
import { usePlacesAutocomplete } from "./use-places-autocomplete";
import styles from "./hero.module.scss";

type Option = {
  id: string;
  title: string;
  subtitle?: string;
  /** Set for static links (popular destinations). Places have no href. */
  href?: string;
  types?: string[];
  /** True for items coming from the user's recent searches. */
  recent?: boolean;
  latitude?: number | null;
  longitude?: number | null;
};

type RecentItem = {
  title: string;
  subtitle?: string;
  latitude?: number | null;
  longitude?: number | null;
};

const MIN_CHARS = 2;
const POPULAR_LIMIT = 6;
const RECENT_LIMIT = 5;
const RECENT_KEY = "tsb_recent_searches";

/** Listing page that receives the search query. Change if your route differs. */
const LISTING_PATH = "/search";

// ---------- Static data ----------
const BG_SLIDES = [
  "/images/home/sliders/home-filter-bg-3.jpg",
  "/images/home/sliders/paris.jpg",
  "/images/home/sliders/cappadocia.jpg",
  "/images/home/sliders/home-filter-bg-4.jpg",
  "/images/home/sliders/amsterdam.jpg",
  "/images/home/sliders/home-filter-bg-5.jpg",
  "/images/home/sliders/home-filter-bg-6.jpg",
];

const POPULAR_DESTINATIONS: Option[] = [
  { id: "turkey", href: "/turkey-tours", title: "Turkey" },
  { id: "egypt", href: "/egypt-tours", title: "Egypt" },
  { id: "tanzania", href: "/tanzania-tours", title: "Tanzania" },
  { id: "nepal", href: "/nepal-tours", title: "Nepal" },
  { id: "vietnam", href: "/vietnam-tours", title: "Vietnam" },
  { id: "sri-lanka", href: "/sri-lanka-tours", title: "Sri Lanka" },
  { id: "greece", href: "/greece-tours", title: "Greece" },
  { id: "ecuador", href: "/ecuador-tours", title: "Ecuador" },
  { id: "maldives", href: "/maldives-tours", title: "Maldives" },
];

const TRENDING: { href: string; label: string }[] = [
  { href: "/turkey-istanbul-tours", label: "Istanbul" },
  { href: "/turkey-cappadocia-tours", label: "Cappadocia" },
  { href: "/france-paris-tours", label: "Paris" },
  { href: "/netherlands-amsterdam-tours", label: "Amsterdam" },
  { href: "/italy-rome-tours", label: "Rome" },
  { href: "/turkey-pamukkale-tours", label: "Pamukkale" },
];

// ---------- Icons ----------
const Icon = {
  pin: (
    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
      <path d="M20 10c0 6-8 12-8 12s-8-6-8-12a8 8 0 0 1 16 0Z" />
      <circle cx="12" cy="10" r="3" />
    </svg>
  ),
  globe: (
    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
      <circle cx="12" cy="12" r="9" />
      <path d="M3 12h18" />
      <path d="M12 3a14 14 0 0 1 0 18a14 14 0 0 1 0-18Z" />
    </svg>
  ),
  landmark: (
    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
      <path d="M3 21h18" />
      <path d="M5 21V10" />
      <path d="M9 21V10" />
      <path d="M15 21V10" />
      <path d="M19 21V10" />
      <path d="M12 3 3 8h18l-9-5Z" />
    </svg>
  ),
  people: (
    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
      <circle cx="9" cy="8" r="3.5" />
      <path d="M2.5 20c0-3.6 2.9-6.5 6.5-6.5s6.5 2.9 6.5 6.5" />
      <path d="M16 4.6a3.5 3.5 0 0 1 0 6.8M18.5 13.8c2 .9 3.5 3 3.5 6.2" />
    </svg>
  ),
  chevron: (
    <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
      <path d="m6 9 6 6 6-6" />
    </svg>
  ),
  clock: (
    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
      <circle cx="12" cy="12" r="9" />
      <path d="M12 7v5l3 2" />
    </svg>
  ),
  close: (
    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
      <path d="M18 6 6 18" />
      <path d="m6 6 12 12" />
    </svg>
  ),
};

// ---------- Helpers ----------
const plural = (n: number, one: string, many: string) =>
  `${n} ${n === 1 ? one : many}`;

const toLocalISODate = (d: Date) =>
  `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(
    d.getDate(),
  ).padStart(2, "0")}`;

const iconForOption = (item: Option): React.ReactNode => {
  if (item.recent) return Icon.clock;
  const types = item.types ?? [];
  if (
    types.includes("country") ||
    types.includes("administrative_area_level_1")
  ) {
    return Icon.globe;
  }
  if (types.includes("establishment") || types.includes("point_of_interest")) {
    return Icon.landmark;
  }
  return Icon.pin;
};

const loadRecent = (): RecentItem[] => {
  try {
    const raw = window.localStorage.getItem(RECENT_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) return [];
    return parsed
      .filter((x) => x && typeof x.title === "string" && x.title.trim())
      .map((x) => ({
        title: x.title,
        subtitle: x.subtitle,
        latitude: typeof x.latitude === "number" ? x.latitude : null,
        longitude: typeof x.longitude === "number" ? x.longitude : null,
      }))
      .slice(0, RECENT_LIMIT);
  } catch {
    return [];
  }
};

const persistRecent = (items: RecentItem[]) => {
  try {
    window.localStorage.setItem(RECENT_KEY, JSON.stringify(items));
  } catch {
    /* storage unavailable (private mode, quota) - ignore */
  }
};

/** Bolds the part of `text` that matches what the user typed. */
function Highlight({ text, term }: { text: string; term: string }) {
  const t = term.trim();
  if (!t) return <>{text}</>;
  const i = text.toLowerCase().indexOf(t.toLowerCase());
  if (i === -1) return <>{text}</>;
  return (
    <>
      {text.slice(0, i)}
      <strong>{text.slice(i, i + t.length)}</strong>
      {text.slice(i + t.length)}
    </>
  );
}

// ---------- Guest counter row ----------
type GuestRowProps = {
  label: string;
  sub: string;
  value: number;
  min: number;
  onChange: (v: number) => void;
};

const GuestRow = ({ label, sub, value, min, onChange }: GuestRowProps) => (
  <div className="guest-row">
    <div className="guest-info">
      <strong>{label}</strong>
      <small>{sub}</small>
    </div>
    <div className="counter">
      <button
        type="button"
        className="counter-btn"
        onClick={() => onChange(value - 1)}
        disabled={value <= min}
      >
        −
      </button>
      <span>{value}</span>
      <button
        type="button"
        className="counter-btn"
        onClick={() => onChange(value + 1)}
      >
        +
      </button>
    </div>
  </div>
);

// ---------- SearchBar (hero) ----------
const SearchBar = () => {
  const router = useRouter();
  const listId = useId();

  const [open, setOpen] = useState(false);
  const [slideIdx, setSlideIdx] = useState(0);
  const [activeIndex, setActiveIndex] = useState(-1);
  const [recent, setRecent] = useState<RecentItem[]>([]);
  const [coords, setCoords] = useState<{ lat: number; lng: number } | null>(
    null,
  );

  const {
    query: destQuery,
    onType,
    choose,
    resume,
    suggestions,
    status,
    hasTerm,
  } = usePlacesAutocomplete({ minChars: MIN_CHARS });

  const [checkIn, setCheckIn] = useState("");
  const [checkOut, setCheckOut] = useState("");

  const [guestsOpen, setGuestsOpen] = useState(false);
  const [adults, setAdults] = useState(2);
  const [children, setChildren] = useState(0);
  const [rooms, setRooms] = useState(1);

  const wrapRef = useRef<HTMLDivElement>(null);
  const destInputRef = useRef<HTMLInputElement>(null);
  const keyboardNavRef = useRef(false);

  const today = toLocalISODate(new Date());
  const trimmedQuery = destQuery.trim();

  const guestsText = [
    plural(adults, "Adult", "Adults"),
    ...(children > 0 ? [plural(children, "Child", "Children")] : []),
    plural(rooms, "Room", "Rooms"),
  ].join(", ");

  // Load recent searches once on the client
  useEffect(() => {
    setRecent(loadRecent());
  }, []);

  const saveRecent = useCallback((item: RecentItem) => {
    const title = item.title.trim();
    if (!title) return;
    setRecent((prev) => {
      const next = [
        {
          title,
          subtitle: item.subtitle,
          latitude: item.latitude,
          longitude: item.longitude,
        },
        ...prev.filter((r) => r.title.toLowerCase() !== title.toLowerCase()),
      ].slice(0, RECENT_LIMIT);
      persistRecent(next);
      return next;
    });
  }, []);

  const clearRecent = () => {
    setRecent([]);
    persistRecent([]);
    setActiveIndex(-1);
  };

  const recentOptions: Option[] = useMemo(
    () =>
      recent.map((r, i) => ({
        id: `recent-${i}-${r.title}`,
        title: r.title,
        subtitle: r.subtitle,
        latitude: r.latitude,
        longitude: r.longitude,
        recent: true,
      })),
    [recent],
  );

  // What the dropdown lists: recent + popular destinations, or API suggestions.
  const options: Option[] = useMemo(() => {
    if (!hasTerm) {
      return [...recentOptions, ...POPULAR_DESTINATIONS.slice(0, POPULAR_LIMIT)];
    }
    return suggestions.map((s) => ({
      id: s.id,
      title: s.title,
      subtitle: s.subtitle,
      types: s.types,
      latitude: s.latitude,
      longitude: s.longitude,
    }));
  }, [hasTerm, suggestions, recentOptions]);

  const recentCount = hasTerm ? 0 : recentOptions.length;

  // Background rotation
  useEffect(() => {
    const id = setInterval(() => {
      setSlideIdx((i) => (i + 1) % BG_SLIDES.length);
    }, 7000);
    return () => clearInterval(id);
  }, []);

  // Close popovers on outside click
  useEffect(() => {
    const onDoc = (e: MouseEvent) => {
      if (wrapRef.current && !wrapRef.current.contains(e.target as Node)) {
        setOpen(false);
        setGuestsOpen(false);
      }
    };
    document.addEventListener("mousedown", onDoc);
    return () => document.removeEventListener("mousedown", onDoc);
  }, []);

  // New list -> no highlighted row
  useEffect(() => {
    setActiveIndex(-1);
  }, [options]);

  // Keep the keyboard-highlighted row visible
  useEffect(() => {
    if (activeIndex < 0 || !keyboardNavRef.current) return;
    document
      .getElementById(`${listId}-opt-${activeIndex}`)
      ?.scrollIntoView({ block: "nearest" });
  }, [activeIndex, listId]);

  /** Builds the listing URL, e.g. /search?term=Istanbul&lat=41.0&lng=28.9&checkIn=...&adults=2 */
  const buildSearchUrl = (term: string) => {
    const params = new URLSearchParams();
    params.set("term", term);
    if (coords) {
      params.set("lat", String(coords.lat));
      params.set("lng", String(coords.lng));
    }
    if (checkIn) params.set("checkIn", checkIn);
    if (checkOut) params.set("checkOut", checkOut);
    params.set("adults", String(adults));
    params.set("children", String(children));
    params.set("rooms", String(rooms));
    return `${LISTING_PATH}?${params.toString()}`;
  };

  const doSearch = () => {
    if (!trimmedQuery) {
      setOpen(true);
      destInputRef.current?.focus();
      return;
    }
    saveRecent({
      title: trimmedQuery,
      latitude: coords?.lat,
      longitude: coords?.lng,
    });
    setOpen(false);
    setGuestsOpen(false);
    router.push(buildSearchUrl(trimmedQuery));
  };

  const clearInput = () => {
    setCoords(null);
    onType("");
    setActiveIndex(-1);
    setOpen(true);
    destInputRef.current?.focus();
  };

  const chooseOption = (item: Option) => {
    if (item.href) {
      window.location.assign(item.href);
      return;
    }
    setCoords(
      item.latitude != null && item.longitude != null
        ? { lat: item.latitude, lng: item.longitude }
        : null,
    );
    saveRecent({
      title: item.title,
      subtitle: item.subtitle,
      latitude: item.latitude,
      longitude: item.longitude,
    });
    choose(item.title);
    setOpen(false);
    setActiveIndex(-1);
  };

  const onDestKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    switch (e.key) {
      case "ArrowDown":
        e.preventDefault();
        if (!open) {
          setOpen(true);
          return;
        }
        if (options.length) {
          keyboardNavRef.current = true;
          setActiveIndex((i) => (i + 1) % options.length);
        }
        break;
      case "ArrowUp":
        e.preventDefault();
        if (!open) {
          setOpen(true);
          return;
        }
        if (options.length) {
          keyboardNavRef.current = true;
          setActiveIndex((i) => (i <= 0 ? options.length - 1 : i - 1));
        }
        break;
      case "Enter":
        // With a highlighted row, pick it. Otherwise let the form submit.
        if (open && activeIndex >= 0 && options[activeIndex]) {
          e.preventDefault();
          chooseOption(options[activeIndex]);
        }
        break;
      case "Escape":
        if (open) {
          e.preventDefault();
          setOpen(false);
          setActiveIndex(-1);
        }
        break;
      case "Tab":
        setOpen(false);
        break;
    }
  };

  const renderOption = (item: Option, index: number) => {
    const isPlace = !item.href;
    return (
      <a
        key={item.id}
        id={`${listId}-opt-${index}`}
        role="option"
        aria-selected={index === activeIndex}
        href={item.href ?? "#"}
        title={item.subtitle ? `${item.title}, ${item.subtitle}` : item.title}
        className={styles.suggItem}
        onMouseEnter={() => {
          keyboardNavRef.current = false;
          setActiveIndex(index);
        }}
        onClick={(e) => {
          if (isPlace) {
            e.preventDefault();
            chooseOption(item);
          }
        }}
      >
        <span className={styles.suggThumb}>{iconForOption(item)}</span>
        <span>
          <span className={styles.suggTitle}>
            {isPlace && !item.recent ? (
              <Highlight text={item.title} term={destQuery} />
            ) : (
              item.title
            )}
          </span>
          {item.subtitle && (
            <small style={{ display: "block", opacity: 0.6 }}>
              {item.subtitle}
            </small>
          )}
        </span>
      </a>
    );
  };

  const renderDropdownBody = () => {
    if (hasTerm && status === "error") {
      return (
        <div className="hs-empty" role="status">
          Couldn’t load suggestions. Press Search to continue.
        </div>
      );
    }

    if (hasTerm && options.length === 0) {
      return (
        <div className="hs-empty" role="status">
          {status === "success"
            ? `No results for “${trimmedQuery}”`
            : "Searching…"}
        </div>
      );
    }

    return (
      <div
        role="listbox"
        id={listId}
        aria-label={hasTerm ? "Places" : "Recent and popular destinations"}
        aria-busy={status === "loading"}
        className={styles.suggList}
        style={status === "loading" ? { opacity: 0.6 } : undefined}
      >
        {/* Recent searches */}
        {recentCount > 0 && (
          <div
            className={styles.suggSection}
            role="presentation"
            style={{
              display: "flex",
              alignItems: "center",
              justifyContent: "space-between",
            }}
          >
            <span>Recent searches</span>
            <button
              type="button"
              onMouseDown={(e) => e.preventDefault()}
              onClick={clearRecent}
              style={{
                background: "none",
                border: 0,
                padding: 0,
                cursor: "pointer",
                font: "inherit",
                fontSize: 12,
                textDecoration: "underline",
                opacity: 0.7,
                color: "inherit",
              }}
            >
              Clear
            </button>
          </div>
        )}
        {options.slice(0, recentCount).map((item, i) => renderOption(item, i))}

        {/* Popular destinations or API places */}
        <div className={styles.suggSection} role="presentation">
          {hasTerm ? "Places" : "Popular destinations"}
        </div>
        {options
          .slice(recentCount)
          .map((item, i) => renderOption(item, i + recentCount))}
      </div>
    );
  };

  return (
    <section className={styles.hero} aria-label="Find your next tour">
      <div className={styles.heroImg}>
        {BG_SLIDES.map((src, i) => (
          // eslint-disable-next-line @next/next/no-img-element
          <img
            key={src}
            src={src}
            alt=""
            aria-hidden="true"
            className={`${styles.heroPhoto} ${i === slideIdx ? styles.heroPhotoActive : ""}`}
            onError={(e) => {
              (e.currentTarget as HTMLImageElement).style.display = "none";
            }}
          />
        ))}
        <div className={styles.heroScrim} />
      </div>

      <div className={`${styles.heroInner} tw-font-display`}>
        <div>
          <h1 className={styles.heroTitle}>
            TravelShop Booking
            <br />
            Book Your World
          </h1>
          <p className={styles.heroLede}>
            Search, compare and book 15,000+ handpicked multiday tours worldwide
            — with trusted reviews, great prices and flexible cancellation.
          </p>
        </div>

        <div ref={wrapRef}>
          <div className="hs-wrap">
            <form
              className="hs-card"
              onSubmit={(e) => {
                e.preventDefault();
                doSearch();
              }}
            >
              {/* Destination */}
              <div className="hs-field hs-dest">
                <label className="hs-label" htmlFor="hero-destination">
                  Where are you going?
                </label>
                <div className="hs-control">
                  <span className="hs-icon">{Icon.pin}</span>
                  <input
                    id="hero-destination"
                    ref={destInputRef}
                    type="text"
                    className="hs-input"
                    placeholder="Search destinations or tours"
                    autoComplete="off"
                    spellCheck={false}
                    maxLength={100}
                    enterKeyHint="search"
                    role="combobox"
                    aria-expanded={open}
                    aria-controls={listId}
                    aria-autocomplete="list"
                    aria-activedescendant={
                      open && activeIndex >= 0
                        ? `${listId}-opt-${activeIndex}`
                        : undefined
                    }
                    value={destQuery}
                    onFocus={() => {
                      setOpen(true);
                      resume();
                    }}
                    onKeyDown={onDestKeyDown}
                    onChange={(e) => {
                      onType(e.target.value);
                      setCoords(null);
                      setOpen(true);
                    }}
                  />
                  {destQuery.length > 0 && (
                    <button
                      type="button"
                      className="hs-clear"
                      aria-label="Clear search"
                      title="Clear"
                      // keep focus in the input
                      onMouseDown={(e) => e.preventDefault()}
                      onClick={clearInput}
                      style={{
                        display: "inline-flex",
                        alignItems: "center",
                        justifyContent: "center",
                        flexShrink: 0,
                        width: 22,
                        height: 22,
                        marginLeft: 6,
                        padding: 0,
                        border: 0,
                        borderRadius: "50%",
                        background: "rgba(0,0,0,0.08)",
                        color: "inherit",
                        cursor: "pointer",
                      }}
                    >
                      {Icon.close}
                    </button>
                  )}
                </div>

                {open && <div className="hs-dropdown">{renderDropdownBody()}</div>}
              </div>

              {/* Check-in */}
              <DateField
                id="hero-checkin"
                label="Check-in"
                value={checkIn}
                min={today}
                onChange={(v) => {
                  setCheckIn(v);
                  if (checkOut && v && checkOut < v) setCheckOut("");
                }}
              />

              {/* Check-out */}
              <DateField
                id="hero-checkout"
                label="Check-out"
                value={checkOut}
                min={checkIn || today}
                onChange={setCheckOut}
              />

              {/* Guests & rooms */}
              <div className="hs-field hs-guests">
                <label className="hs-label">Guests &amp; Rooms</label>
                <div
                  className="hs-control hs-guest-control"
                  role="button"
                  tabIndex={0}
                  onClick={() => setGuestsOpen((o) => !o)}
                  onKeyDown={(e) => {
                    if (e.key === "Enter" || e.key === " ") {
                      e.preventDefault();
                      setGuestsOpen((o) => !o);
                    }
                  }}
                >
                  <span className="hs-icon">{Icon.people}</span>
                  <span className="hs-value hs-ellipsis">{guestsText}</span>
                  <span className={`hs-chevron ${guestsOpen ? "rotate" : ""}`}>
                    {Icon.chevron}
                  </span>
                </div>

                {guestsOpen && (
                  <div className="guest-popup">
                    <GuestRow
                      label="Adults"
                      sub="Age 12+"
                      value={adults}
                      min={1}
                      onChange={setAdults}
                    />
                    <GuestRow
                      label="Children"
                      sub="Age 2–11"
                      value={children}
                      min={0}
                      onChange={setChildren}
                    />
                    <GuestRow
                      label="Rooms"
                      sub="Number of rooms"
                      value={rooms}
                      min={1}
                      onChange={setRooms}
                    />
                    <div className="guest-footer">
                      <button
                        type="button"
                        className="guest-done"
                        onClick={() => setGuestsOpen(false)}
                      >
                        Done
                      </button>
                    </div>
                  </div>
                )}
              </div>

              {/* Submit */}
              <div className="hs-submit">
                <button type="submit" className="hs-btn">
                  Search
                </button>
              </div>
            </form>
          </div>

          <div className={styles.heroChips}>
            <span className={styles.chipsLabel}>Trending:</span>
            {TRENDING.map((opt) => (
              <a key={opt.href} href={opt.href} className={styles.chip}>
                {opt.label}
              </a>
            ))}
          </div>
        </div>
      </div>
    </section>
  );
};

export default SearchBar;