"use client";
import { useEffect, useRef, useState } from "react";
import Image from "next/image";
import { shimmer } from "@/components/utils/shimmer";
import cdnImage from "@/helpers/cdnImage";
import styles from "./listing-card.module.scss";

const toBase64 = (str: string) =>
  typeof window === "undefined"
    ? Buffer.from(str).toString("base64")
    : window.btoa(str);

// How many images a card may cycle through. Most tours carry far more in
// `media`; capping keeps the DOM light and the scrub zones meaningful. Keep in
// sync with CACHE_MEDIA_LIMIT in apiv3's RefreshTourCategoryPageCache job — the
// baked category cache trims media to that many images per tour.
const MAX_IMAGES = 4;

type MediaItem = {
  id?: number | string;
  collection_name?: string;
  high?: string;
  main?: string;
  thumb?: string;
};

// Ordered, de-duplicated, capped image list for a card. The `main` collection
// image leads; the rest (`default`) follow in their given order. Falls back to
// the flat `detail.image` when a tour has no usable media array.
function buildImages(detail: any): MediaItem[] {
  const media: MediaItem[] = Array.isArray(detail.media) ? detail.media : [];
  const ordered = [
    ...media.filter((m) => m?.collection_name === "main"),
    ...media.filter((m) => m?.collection_name !== "main"),
  ];

  const seen = new Set<number | string>();
  const list: MediaItem[] = [];
  for (const m of ordered) {
    if (!m || (!m.high && !m.main && !m.thumb)) continue;
    if (m.id != null && seen.has(m.id)) continue;
    if (m.id != null) seen.add(m.id);
    list.push(m);
    if (list.length >= MAX_IMAGES) break;
  }

  if (list.length === 0 && detail.image) {
    list.push({ id: "fallback", high: detail.image, main: detail.image });
  }
  return list;
}

// One image inside the gallery. Keeps the listing card's source-fallback
// behaviour: try the high (1200×800) conversion first — Next downscales it to
// the rendered ~350/700px webp — then the original `main` on error.
function Slide({
  image,
  alt,
  priority,
  eager = false,
}: {
  image: MediaItem;
  alt: string;
  priority: boolean;
  // True for secondary slides (i > 0). They only ever mount once we've decided
  // to show them (desktop hover / swipe under way), so they fetch `eager` —
  // deferring an image we just chose to display would only add latency.
  eager?: boolean;
}) {
  const sources = [image.high, image.main, image.thumb]
    .filter((s): s is string => typeof s === "string" && s.length > 0)
    .map(cdnImage);

  const [index, setIndex] = useState(0);
  const [loaded, setLoaded] = useState(false);

  if (sources.length === 0) {
    return <span className={styles.imgPlaceholder} />;
  }

  // First image is `priority` on first-row cards (LCP), `lazy` elsewhere.
  const loadingProps = priority
    ? { priority: true as const }
    : { loading: (eager ? "eager" : "lazy") as "eager" | "lazy" };

  return (
    <>
      {/* Animated skeleton overlaying the image (z-index:1) until it paints;
          it fades OUT to reveal the image underneath. The fade must live on
          this overlay, never as opacity:0 on the <img> itself: browsers treat
          a CSS-invisible image as a tracking pixel and fetch it IMMEDIATELY,
          silently disabling loading="lazy" — which made every card image on
          the page download up front. The priority (LCP) image skips it. */}
      {!priority && (
        <span
          className={styles.slideLoading}
          aria-hidden="true"
          style={{ opacity: loaded ? 0 : 1, transition: "opacity 0.3s ease" }}
        />
      )}
      <Image
        src={sources[index]}
        onLoad={() => setLoaded(true)}
        onError={() => {
          setLoaded(false);
          setIndex((prev) => (prev < sources.length - 1 ? prev + 1 : prev));
        }}
        alt={alt}
        title={alt}
        width={350}
        height={233}
        // Widths track the real grid in tour-list.tsx (1/2/3/4 cols at
        // 640/1024/1280). Mobile is deliberately UNDER-declared (~60vw, not the
        // true ~93vw single full-width card): on a DPR-3 phone 93vw would pull
        // the 1200w candidate (~90KB). 60vw caps the request at the 750w
        // candidate ≈ 2× the card's actual pixels — visually identical on
        // photos, ~half the bytes. This is the mobile-LCP lever. Tablet/desktop
        // (50/33/25vw) already resolve to ~2× density, so they stay as-is.
        sizes="(max-width: 639px) 60vw, (max-width: 1023px) 50vw, (max-width: 1279px) 33vw, 25vw"
        quality={75}
        {...loadingProps}
        placeholder={`data:image/svg+xml;base64,${toBase64(shimmer(350, 233))}`}
      />
    </>
  );
}

export default function CardGallery({
  detail,
  priority = false,
}: {
  detail: any;
  priority?: boolean;
}) {
  const images = buildImages(detail);
  const trackRef = useRef<HTMLDivElement>(null);
  const [active, setActive] = useState(0);
  // Desktop: a mouse hover loads every remaining image at once (fast connection
  // assumed) so the scrub is instant at any cursor position. One-way latch.
  const [hovered, setHovered] = useState(false);
  // Desktop scrub arms only after the cursor has lingered briefly on the card.
  // Loading (above) is instant on enter; this delay gates only the *movement* —
  // without it, sweeping the mouse across the grid scrubs every card it
  // crosses and the whole page looks like the photos are dancing.
  const [scrubArmed, setScrubArmed] = useState(false);
  const scrubTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

  const cancelScrubTimer = () => {
    if (scrubTimer.current) {
      clearTimeout(scrubTimer.current);
      scrubTimer.current = null;
    }
  };

  // Clear a pending scrub-arm timer if the card unmounts mid-hover.
  useEffect(() => cancelScrubTimer, []);
  // Touch: the furthest slide a swipe has moved toward (monotonic — slides
  // never unmount once loading). Secondary images mount only when a swipe
  // actually starts. They must NOT be pre-mounted with `loading="lazy"`:
  // the clipped slides sit a card-width to the side, well inside the browser's
  // lazy prefetch distance (~1250px, sideways too), so pre-mounting made every
  // on-screen card download all four photos on page load.
  const [reached, setReached] = useState(0);

  // Single image (or none): keep the original static behaviour — no scroll
  // track, no dots, no scrub.
  if (images.length <= 1) {
    return images.length === 1 ? (
      <Slide image={images[0]} alt={detail.name} priority={priority} />
    ) : (
      <span className={styles.imgPlaceholder} />
    );
  }

  // The active dot and the touch lazy-load trigger both derive from the
  // track's scroll offset, so native swipes and the desktop scrub share one
  // source of truth.
  const handleScroll = () => {
    const el = trackRef.current;
    if (!el) return;
    const ratio = el.scrollLeft / el.clientWidth;
    setActive((prev) => {
      const next = Math.round(ratio);
      return prev === next ? prev : next;
    });
    // `ceil`: the instant a swipe starts moving toward slide n, mount it so the
    // fetch gets a head start before the swipe lands. At rest this stays 0.
    // (Mutating a slide's *contents* mid-scroll is safe — the track's own
    // children are stable; the old first-swipe jank was the hover transform.)
    const reach = Math.ceil(ratio);
    setReached((prev) => (reach > prev ? reach : prev));
  };

  const handlePointerEnter = (e: React.PointerEvent<HTMLDivElement>) => {
    if (e.pointerType !== "mouse") return;
    // Hover-intent: both the image fetch and the scrub wait out the same short
    // linger. A cursor merely passing over the card on its way elsewhere
    // neither flips its photos nor pulls 3 images per grazed card. `hovered`
    // stays a one-way latch (images keep loading after leave); `scrubArmed`
    // disarms on leave.
    cancelScrubTimer();
    scrubTimer.current = setTimeout(() => {
      setHovered(true);
      setScrubArmed(true);
    }, 120);
  };

  // Desktop only: map the cursor's horizontal position to an image, the way
  // Hepsiburada's grid cards do. Touch is left to native scroll-snap.
  const handlePointerMove = (e: React.PointerEvent<HTMLDivElement>) => {
    if (e.pointerType !== "mouse" || !scrubArmed) return;
    const el = trackRef.current;
    if (!el) return;
    const rect = el.getBoundingClientRect();
    const ratio = (e.clientX - rect.left) / rect.width;
    const zone = Math.min(
      images.length - 1,
      Math.max(0, Math.floor(ratio * images.length)),
    );
    el.scrollTo({ left: zone * el.clientWidth, behavior: "auto" });
  };

  const handlePointerLeave = (e: React.PointerEvent<HTMLDivElement>) => {
    if (e.pointerType !== "mouse") return;
    // Disarm: the next visit must linger again before the photos move.
    cancelScrubTimer();
    setScrubArmed(false);
    // Reset the scrub back to the first image when the cursor leaves the card.
    trackRef.current?.scrollTo({ left: 0, behavior: "smooth" });
  };

  return (
    <>
      <div
        ref={trackRef}
        // Marks this as the card's own horizontal scroller so an enclosing
        // Embla carousel (TourCarousel) can let swipes here scroll the photos
        // instead of paging the carousel. See TourCarousel's `watchDrag`.
        data-card-gallery=""
        className={styles.gallery}
        onScroll={handleScroll}
        onPointerEnter={handlePointerEnter}
        onPointerMove={handlePointerMove}
        onPointerLeave={handlePointerLeave}
      >
        {images.map((image, i) => {
          // The slide BOX always renders, so the track is full-width and
          // swipe-ready immediately. The IMAGE inside is deferred: slide 0
          // always; the rest mount on desktop hover (all at once) or as a
          // swipe reaches them on touch. A cold page load therefore fetches
          // exactly one image per card — even for the priority first row.
          const showImage = i === 0 || hovered || i <= reached;
          return (
            <div className={styles.slide} key={image.id ?? i}>
              {showImage ? (
                <Slide
                  image={image}
                  alt={detail.name}
                  priority={priority && i === 0}
                  eager={i > 0}
                />
              ) : (
                <span className={styles.slideLoading} aria-hidden="true" />
              )}
            </div>
          );
        })}
      </div>
      <div className={styles.dots} aria-hidden="true">
        {images.map((image, i) => (
          <span
            key={image.id ?? i}
            className={`${styles.dot} ${i === active ? styles.dotActive : ""}`}
          />
        ))}
      </div>
    </>
  );
}
