import Image from "next/image";

export default function BlogPosts({ posts }: { posts: any }) {
  return (
    <section className="tw-py-12 md:tw-py-16 tw-bg-white tw-font-display">
      <div className="tw-container tw-mx-auto tw-max-w-[1320px] tw-px-6 md:tw-px-8 lg:tw-px-10">
        {/* Section header */}
        <div className="tw-flex tw-flex-col sm:tw-flex-row sm:tw-items-end sm:tw-justify-between tw-gap-2 tw-mb-10">
          <div>
            <h2 className="tw-text-[clamp(24px,3vw,34px)] tw-font-bold tw-tracking-tight tw-text-[#14101c] tw-m-0">
              Latest Travel Guides
            </h2>
            <p className="tw-mt-1.5 tw-mb-0 tw-max-w-[60ch] tw-text-sm tw-text-[#6b6577]">
              View our travel guides giving you travel insights, ideas, and tips
              across the world.
            </p>
          </div>
          <a
            href="/blog"
            target="_blank"
            className="tw-inline-flex tw-items-center tw-gap-1.5 tw-text-[14px] tw-font-semibold tw-text-[#854ec9] hover:tw-text-[#6a3da4] tw-whitespace-nowrap tw-shrink-0 tw-no-underline tw-transition-colors"
          >
            All travel guides <span aria-hidden="true">→</span>
          </a>
        </div>

        {/* Cards */}
        <div className="tw-grid tw-grid-cols-1 sm:tw-grid-cols-2 lg:tw-grid-cols-4 tw-gap-6 lg:tw-gap-7">
          {posts.map((post: any) => (
            <article key={post.id} className="tw-group tw-flex tw-flex-col">
              <a
                href={"/blog/" + post.slug}
                title={post.title}
                target="_blank"
                className="tw-block tw-no-underline"
              >
                <div className="tw-relative tw-aspect-[4/3] tw-rounded-xl tw-overflow-hidden tw-bg-[#f3f1f7]">
                  <Image
                    src={post.main_image}
                    alt={post.title}
                    fill
                    sizes="(max-width: 640px) 100vw, (max-width: 1024px) 50vw, 25vw"
                    quality={100}
                    loading="lazy"
                    className="tw-object-cover tw-transition-transform tw-duration-500 group-hover:tw-scale-105"
                  />
                </div>
              </a>

              <div className="tw-mt-3.5 tw-flex tw-flex-col tw-flex-1">
                <a
                  href={"/blog/" + post.slug}
                  title={post.title}
                  target="_blank"
                  className="tw-no-underline"
                >
                  <h3
                    className="tw-font-bold tw-text-[16px] tw-leading-[1.35] tw-text-[#14101c] tw-m-0 group-hover:tw-text-[#854ec9] tw-transition-colors"
                    style={{
                      overflow: "hidden",
                      textOverflow: "ellipsis",
                      display: "-webkit-box",
                      WebkitLineClamp: 2,
                      WebkitBoxOrient: "vertical",
                    }}
                    dangerouslySetInnerHTML={{ __html: post.title }}
                  />
                </a>

                <div
                  className="tw-mt-2 tw-text-[14px] tw-leading-[1.5] tw-text-[#5d556c]"
                  style={{
                    overflow: "hidden",
                    textOverflow: "ellipsis",
                    display: "-webkit-box",
                    WebkitLineClamp: 2,
                    WebkitBoxOrient: "vertical",
                  }}
                  dangerouslySetInnerHTML={{ __html: post.excerpt }}
                />

                <a
                  href={"/blog/" + post.slug}
                  title={post.title}
                  target="_blank"
                  className="tw-inline-flex tw-items-center tw-gap-1.5 tw-mt-3 tw-text-[14px] tw-font-semibold tw-text-[#854ec9] group-hover:tw-text-[#6a3da4] tw-no-underline tw-transition-colors"
                >
                  Read more <span aria-hidden="true">→</span>
                </a>
              </div>
            </article>
          ))}
        </div>

        {/* Bottom CTA */}
        <div className="tw-mt-10 tw-flex tw-justify-center">
          <a
            href="/blog"
            target="_blank"
            className="tw-inline-flex tw-items-center tw-gap-2 tw-bg-[#854ec9] hover:tw-bg-[#6a3da4] tw-text-white tw-font-semibold tw-text-[15px] tw-px-6 tw-py-3.5 tw-rounded-full tw-no-underline tw-transition-colors"
          >
            See all travel guides <span aria-hidden="true">→</span>
          </a>
        </div>
      </div>
    </section>
  );
}
