"use client";
import { useEffect, useState, type CSSProperties } from "react";
import useEmblaCarousel from "embla-carousel-react";
import ListingCard from "./card/listing-card";

// Line-arrow icon (←/→) matching the reference design (data.jsx arrowL/arrowR).
function Arrow({ dir }: { dir: "left" | "right" }) {
  return (
    <svg
      width={18}
      height={18}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth={1.6}
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
    >
      {dir === "left" ? (
        <>
          <path d="M19 12H5" />
          <path d="M11 19l-7-7 7-7" />
        </>
      ) : (
        <>
          <path d="M5 12h14" />
          <path d="M13 5l7 7-7 7" />
        </>
      )}
    </svg>
  );
}

// Arrow "chrome" (bg/border/shadow/z-index/position) lives in inline styles:
// with preflight off + global Bootstrap, arbitrary Tailwind classes for these
// don't apply reliably (transparent arrows, square buttons, stacking bugs).
const arrowStyle = (side: "left" | "right"): CSSProperties => ({
  appearance: "none",
  WebkitAppearance: "none",
  border: "1px solid #e2dced",
  color: "#14101c",
  background: "#fff",
  zIndex: 3,
  [side]: "-22px",
  // Pull the button up by half its own height so `top: 50%` lands its center
  // on the card's vertical midpoint (Tailwind transform utilities are unreliable
  // here with preflight off — keep it inline like the rest of the chrome).
  transform: "translateY(-50%)",
  boxShadow: "0 6px 16px rgba(20,16,28,0.16), 0 2px 5px rgba(20,16,28,0.10)",
});

/**
 * Reusable tour-card carousel (Embla). Desktop: arrows page by the number of
 * visible cards (xl 4 / lg 3 / sm 2), hidden at the ends. Mobile: ~1.5 cards,
 * swipe only, full-bleed with a 16px inset on the first card and a 16px gap
 * after the last. Expects a parent container with 16px (px-4) side padding.
 */
const TourCarousel = ({
  tours,
  prices,
  priceLoading,
}: {
  tours: any[];
  prices: any[];
  priceLoading: boolean;
}) => {
  const [emblaRef, emblaApi] = useEmblaCarousel({
    align: "start",
    containScroll: "trimSnaps",
    slidesToScroll: 1,
    breakpoints: {
      "(min-width: 640px)": { slidesToScroll: 2 },
      "(min-width: 1024px)": { slidesToScroll: 3 },
      "(min-width: 1280px)": { slidesToScroll: 4 },
    },
    // Don't hijack a drag that begins on a card's own image gallery — let that
    // gallery scroll its photos. Single-image cards have no gallery, so they
    // (and the gaps/body) still drag the carousel normally. Desktop also pages
    // via the arrows. (Embla skips the drag when this returns false.)
    watchDrag: (_emblaApi, event) => {
      const target = event.target as Element | null;
      return !target?.closest("[data-card-gallery]");
    },
  });
  const [nav, setNav] = useState({ prev: false, next: false });

  useEffect(() => {
    if (!emblaApi) return;
    const update = () =>
      setNav({ prev: emblaApi.canScrollPrev(), next: emblaApi.canScrollNext() });
    update();
    emblaApi.on("select", update);
    emblaApi.on("reInit", update);
    return () => {
      emblaApi.off("select", update);
      emblaApi.off("reInit", update);
    };
  }, [emblaApi]);

  if (tours.length === 0) return null;

  return (
    // On mobile the viewport bleeds past the parent's 16px side padding so
    // cards clip at the screen edge; slide padding restores the 16px inset.
    <div className="tw-relative -tw-mx-4 md:tw-mx-0">
      {nav.prev && (
        <button
          type="button"
          onClick={() => emblaApi?.scrollPrev()}
          aria-label="Scroll left"
          style={arrowStyle("left")}
          className="tw-absolute tw-top-1/2 tw-hidden md:tw-grid tw-place-items-center tw-h-11 tw-w-11 tw-rounded-full"
        >
          <Arrow dir="left" />
        </button>
      )}

      <div ref={emblaRef} className="tw-overflow-hidden">
        {/* pt/pb keep the card hover shadow inside the clipped viewport. */}
        <div
          className="tw-flex md:-tw-ml-6 tw-pt-3 tw-pb-6"
          // `manipulation` (pan-x + pan-y + pinch) — NOT `pan-y`. A `pan-y`
          // ancestor would, by touch-action's top-down intersection, forbid
          // horizontal panning in the whole subtree, blocking each card's own
          // image gallery from scrolling its photos on touch. Allowing pan-x
          // lets that native gallery scroll; the carousel itself is still
          // dragged by Embla's JS (preventDefault), and `watchDrag` keeps Embla
          // from hijacking a swipe that begins on a gallery.
          style={{ touchAction: "manipulation", overscrollBehaviorX: "contain" }}
        >
          {tours.map((tour: any, index: number) => (
            <div
              key={tour.id}
              // The last slide adds a right-edge gap on mobile (tw-pr-4). That
              // gap must also be ADDED to the basis, not just padded in —
              // otherwise it eats into the card, so the last card renders ~1rem
              // narrower and its fixed-ratio image looks shorter than the rest.
              // Each mobile breakpoint compensates pr-4 with +1rem of basis,
              // reset at md where the padding is dropped.
              className={`tw-min-w-0 tw-flex-none tw-pl-4 md:tw-pl-6 lg:tw-basis-1/3 xl:tw-basis-1/4 ${
                index === tours.length - 1
                  ? "tw-basis-[calc(66%+2rem)] sm:tw-basis-[calc(50%+1rem)] md:tw-basis-1/2 tw-pr-4 md:tw-pr-0"
                  : "tw-basis-[calc(66%+1rem)] sm:tw-basis-1/2"
              }`}
            >
              <ListingCard
                detail={tour}
                priceLoading={priceLoading}
                priceInfo={prices.find((x: any) => x.tourId === tour.id)}
              />
            </div>
          ))}
        </div>
      </div>

      {nav.next && (
        <button
          type="button"
          onClick={() => emblaApi?.scrollNext()}
          aria-label="Scroll right"
          style={arrowStyle("right")}
          className="tw-absolute tw-top-1/2 tw-hidden md:tw-grid tw-place-items-center tw-h-11 tw-w-11 tw-rounded-full"
        >
          <Arrow dir="right" />
        </button>
      )}
    </div>
  );
};

export default TourCarousel;
