"use client";
import { useState } from "react";
import { useWishlist, type WishlistItem } from "./wishlist-context";

const HEART_PATH =
  "M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z";

// "card" — floating circle over a tour image.
// "link" — inline heart + text ("Add to Wishlist"), e.g. tour detail meta row.
// "icon" — icon-only outlined button, e.g. next to CTA buttons.
type Variant = "card" | "link" | "icon";

export default function WishlistButton({
  tour,
  variant = "card",
  size,
  className = "",
  label,
  activeLabel,
}: {
  tour: WishlistItem;
  variant?: Variant;
  size?: number;
  className?: string;
  /** link variant: text when NOT saved */
  label?: string;
  /** link variant: text when saved */
  activeLabel?: string;
}) {
  const { isFavorite, toggle, hydrated } = useWishlist();
  const [burst, setBurst] = useState(false);
  const active = hydrated && isFavorite(tour.id);
  const isCard = variant === "card";
  const isIcon = variant === "icon";
  const iconSize = size ?? (isCard ? 18 : isIcon ? 18 : 16);

  const onClick = (e: React.MouseEvent) => {
    // Tour cards usually wrap the heart in a link — don't navigate.
    e.preventDefault();
    e.stopPropagation();
    toggle(tour);
    setBurst(true);
    window.setTimeout(() => setBurst(false), 280);
  };

  const wrapperClass = isCard
    ? "tw-grid tw-place-items-center tw-rounded-full tw-border-0 tw-cursor-pointer tw-text-[#2a2336] tw-transition-[transform,color] hover:tw-scale-110 hover:tw-text-[#854ec9] active:tw-scale-90"
    : isIcon
      ? "tw-inline-flex tw-h-9 tw-w-9 tw-items-center tw-justify-center tw-rounded-full tw-bg-[#f4eefb] tw-border-0 tw-cursor-pointer hover:tw-bg-[#e7dcf6] active:tw-scale-90 tw-transition-[background-color,transform]"
      : "tw-inline-flex tw-items-center tw-gap-1.5 tw-bg-transparent tw-border-0 tw-p-0 tw-cursor-pointer tw-font-semibold hover:tw-underline tw-underline-offset-2";

  const wrapperStyle: React.CSSProperties = isCard
    ? {
        width: 30,
        height: 30,
        zIndex: 2,
        background: "rgba(255,255,255,0.92)",
        backdropFilter: "blur(2px)",
        boxShadow: "0 2px 8px rgba(20,16,28,0.18)",
        transform: burst ? "scale(1.12)" : undefined,
      }
    : isIcon
      ? {}
      : { color: "#854ec9", fontSize: 14, lineHeight: 1.2 };

  // Optical alignment: the heart's pointed tip is bottom-heavy, so a tiny
  // upward nudge centers it against the text in the link variant.
  const baseTransform = isCard || isIcon ? "" : "translateY(-0.5px) ";

  return (
    <button
      type="button"
      onClick={onClick}
      aria-pressed={active}
      aria-label={active ? "Remove from wishlist" : "Add to wishlist"}
      title={active ? "Remove from wishlist" : "Save to wishlist"}
      className={`${wrapperClass} ${className}`}
      style={wrapperStyle}
    >
      <svg
        width={iconSize}
        height={iconSize}
        viewBox="0 0 24 24"
        fill={active ? "#854ec9" : "none"}
        stroke={active ? "#854ec9" : isCard ? "currentColor" : "#854ec9"}
        strokeWidth={2}
        strokeLinecap="round"
        strokeLinejoin="round"
        style={{
          display: "block",
          flexShrink: 0,
          transition: "transform 0.18s ease",
          transform: baseTransform + (burst ? "scale(1.25)" : "scale(1)"),
        }}
        aria-hidden="true"
      >
        <path d={HEART_PATH} />
      </svg>
      {variant === "link" && (
        <span>{active ? activeLabel ?? "In Wishlist" : label ?? "Add to Wishlist"}</span>
      )}
    </button>
  );
}
