/**
 * Lokasyonların ata zinciri — TARAYICI tarafı.
 *
 * Sunucu tarafındaki `tourRouteStops` ile aynı bilgiyi (Europe › Turkey › Aydin)
 * verir, ama tur kartının rota modalı gibi 'use client' bileşenler için: X-App-Token
 * gerektiren apiv3 ucuna /api/apiv3 proxy'si üzerinden gidilir ve tüm duraklar
 * toplu uçla (locations/parents?ids=) tek istekte çözülür.
 *
 * Çözülen zincirler modül düzeyinde önbelleklenir; aynı sayfada başka bir kartın
 * modalı açıldığında ortak şehirler (Istanbul, Kusadasi…) yeniden istenmez.
 */

export type LocationCrumb = {
  name: string;
  slug?: string | null;
  type?: string | null;
};

/** locationId → kırıntılar, uzaktan yakına (["Europe", "Turkey", "Aydin"]). */
const cache = new Map<number, LocationCrumb[]>();

export default async function getLocationParents(
  ids: (number | null | undefined)[],
): Promise<Record<number, LocationCrumb[]>> {
  const unique = Array.from(
    new Set(
      ids
        .map((id) => Number(id))
        .filter((id) => Number.isFinite(id) && id > 0),
    ),
  );

  const missing = unique.filter((id) => !cache.has(id));

  if (missing.length > 0) {
    try {
      const res = await fetch(
        `/api/apiv3/locations/parents?ids=${missing.join(",")}`,
        { headers: { Accept: "application/json" } },
      );
      if (res.ok) {
        const json = await res.json();
        const data = json?.data ?? {};
        for (const id of missing) {
          const chain = Array.isArray(data[id]) ? data[id] : [];
          cache.set(
            id,
            // apiv3 en yakın atayı önce döner; breadcrumb ters yönde okunur.
            [...chain]
              .reverse()
              .map((p: any) => ({
                name: p?.name,
                slug: p?.slug ?? null,
                type: p?.type ?? null,
              }))
              .filter((p: LocationCrumb) => !!p.name),
          );
        }
      }
    } catch {
      // Zincir çözülemezse durak adı yalın kalır — modal kırılmaz.
    }
  }

  const out: Record<number, LocationCrumb[]> = {};
  for (const id of unique) out[id] = cache.get(id) ?? [];
  return out;
}
