"use client";
import { useState, useEffect } from "react";
import { getCookie } from "cookies-next";
import postSubscribe from "@/services/subscribe";
import getTourPricing from "@/services/tourPricingService";
import TopTravel from "./top-travel";
import PopularDestinations from "./popular-destinations";
import Categories from "./categories";
import BlogPosts from "./blog";
import SearchBar from "./search-bar";

export default function Page({
  featuredTours,
  tourCategories,
  blogPosts,
}: {
  featuredTours: any;
  tourCategories: any;
  blogPosts: any;
}) {
  const [priceLoading, setPriceLoading] = useState(true);
  const [prices, setPrices] = useState(
    featuredTours.tours.map((item: any) => {
      return {
        tourId: item.id,
        price: 0,
        oldPrice: 0,
        paxLeft: 0,
        currency: "",
      };
    }),
  );

  const [subscribeLoading, setSubscribeLoading] = useState(false);
  const [subscribeMail, setSubscribeMail] = useState("");
  const [subscribeStatus, setSubscribeStatus] = useState("");
  const [subscribeErrorMessage, setSubscribeErrorMessage] = useState("");
  const isEmail = (email: string) =>
    /^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,4}$/i.test(email);

  const subscribePost = async () => {
    if (!subscribeMail || !isEmail(subscribeMail)) {
      setSubscribeErrorMessage("Please specify an email address");
      setSubscribeStatus("error");
    } else {
      setSubscribeLoading(true);
      setSubscribeStatus("");
      await postSubscribe(subscribeMail).then((res) => {
        setSubscribeMail("");
        setSubscribeStatus("success");
        setSubscribeLoading(false);
      });
    }
  };

  useEffect(() => {
    getTourPricing(
      featuredTours.tours.map((tour: any) => tour.id),
      getCookie("currency"),
    ).then((res) => {
      setPrices(
        res.map((item: any) => {
          return {
            tourId: item.id,
            price: item.price,
            oldPrice: item.old_price,
            paxLeft: item.promotionDetail.pax_left ?? 0,
            currency: item.currency,
          };
        }),
      );
      setPriceLoading(false);
    });
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  const jsonLd = {
    "@context": "https://schema.org",
    "@type": "BreadcrumbList",
    itemListElement: [
      {
        "@type": "ListItem",
        position: 1,
        item: { "@id": "https://travelshopbooking.com", name: "Home" },
      },
    ],
  };

  return (
    <main>
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{ __html: JSON.stringify(jsonLd) }}
      />

      <SearchBar />

      <TopTravel
        featuredTours={featuredTours}
        prices={prices}
        priceLoading={priceLoading}
      />

      <PopularDestinations />

      <Categories tourCategories={tourCategories} />

      <BlogPosts posts={blogPosts} />

      <section className="tw-py-12 md:tw-py-16 tw-font-display">
        <div className="tw-container tw-mx-auto tw-max-w-[1320px] tw-px-6 md:tw-px-8 lg:tw-px-10">
          <div className="tw-relative tw-overflow-hidden tw-rounded-3xl tw-bg-[#854ec9] tw-text-white tw-grid tw-grid-cols-1 lg:tw-grid-cols-[1.2fr_1fr] tw-gap-8 tw-items-center tw-p-8 sm:tw-p-10 lg:tw-p-14">
            <div
              aria-hidden
              className="tw-pointer-events-none tw-absolute"
              style={{
                right: -80,
                top: -80,
                width: 320,
                height: 320,
                background:
                  "radial-gradient(circle, rgba(255,255,255,0.18), transparent 70%)",
              }}
            />
            <div
              aria-hidden
              className="tw-pointer-events-none tw-absolute"
              style={{
                left: -40,
                bottom: -60,
                width: 240,
                height: 240,
                background:
                  "radial-gradient(circle, rgba(0,0,0,0.18), transparent 70%)",
              }}
            />

            <div className="tw-relative tw-z-[2]">
              <h2 className="tw-text-[26px] sm:tw-text-[32px] lg:tw-text-[38px] tw-font-extrabold tw-tracking-[-0.03em] tw-leading-[1.05] tw-m-0">
                Steal of the week, in your inbox
              </h2>
              <p className="tw-opacity-90 tw-mt-3 tw-text-[15px] tw-max-w-[50ch]">
                Get up to 50% off a tour every week. Book before it sells out.
              </p>
              <ul className="tw-flex tw-flex-wrap tw-gap-x-5 tw-gap-y-2 tw-mt-4 tw-text-[13px] tw-opacity-90 tw-list-none tw-p-0 tw-m-0">
                <li className="tw-flex tw-items-center tw-gap-1.5">
                  <span className="tw-opacity-70">✓</span>One email a week
                </li>
                <li className="tw-flex tw-items-center tw-gap-1.5">
                  <span className="tw-opacity-70">✓</span>Best price guarantee
                </li>
                <li className="tw-flex tw-items-center tw-gap-1.5">
                  <span className="tw-opacity-70">✓</span>Unsubscribe anytime
                </li>
              </ul>
            </div>

            <div className="tw-relative tw-z-[2]">
              {subscribeStatus == "success" ? (
                <div className="tw-bg-white/20 tw-border tw-border-white/30 tw-rounded-2xl tw-p-5 tw-font-semibold">
                  ✓ You&apos;re in. Your first deal lands in your inbox soon.
                </div>
              ) : (
                <>
                  <form
                    className="tw-flex tw-flex-col sm:tw-flex-row tw-gap-2 tw-bg-white tw-rounded-3xl sm:tw-rounded-full tw-p-1.5"
                    onSubmit={(e) => {
                      e.preventDefault();
                      subscribePost();
                    }}
                  >
                    <input
                      type="email"
                      id="home-subscribe-mail-input"
                      placeholder="you@example.com"
                      aria-label="Email address"
                      value={subscribeMail}
                      onChange={(e) => {
                        setSubscribeMail(e.target.value);
                      }}
                      className="tw-flex-1 tw-min-w-0 tw-border-0 tw-outline-none tw-bg-transparent tw-px-4 tw-py-3 tw-text-[15px] tw-text-[#14101c] tw-rounded-full"
                    />
                    <button
                      type="submit"
                      id="btn-subscribe"
                      disabled={subscribeLoading}
                      className="tw-w-full sm:tw-w-auto tw-flex-shrink-0 tw-bg-[#14101c] tw-text-white tw-font-semibold tw-px-5 tw-py-3 tw-rounded-full tw-border-0 tw-cursor-pointer hover:tw-opacity-90 tw-transition-opacity disabled:tw-opacity-60 disabled:tw-cursor-not-allowed"
                    >
                      {subscribeLoading
                        ? "Subscribing…"
                        : "Get the weekly deal"}
                    </button>
                  </form>
                  {subscribeStatus == "error" && (
                    <p className="tw-text-[13px] tw-text-white tw-font-medium tw-mt-2.5 tw-mb-0">
                      {subscribeErrorMessage}
                    </p>
                  )}
                  <p className="tw-text-[12px] tw-opacity-85 tw-mt-2.5 tw-mb-0">
                    By subscribing, you agree to our{" "}
                    <a
                      href="/terms-of-use"
                      className="tw-text-white tw-underline"
                    >
                      Terms
                    </a>{" "}
                    and{" "}
                    <a
                      href="/privacy-policy"
                      className="tw-text-white tw-underline"
                    >
                      Privacy Policy
                    </a>
                    .
                  </p>
                </>
              )}
            </div>
          </div>
        </div>
      </section>
    </main>
  );
}
